function dump(n, d){
  let s="";
  for(const c of n.children){
    s += "  ".repeat(d)+c.type+" "+JSON.stringify(c.name);
    if(c.type!=="INSTANCE") s += " fills="+JSON.stringify(c.fills?.map(f=>f.type==="SOLID"?f.color:null));
    s += "\n";
    if(c.children && c.children.length) s += dump(c,d+1);
  }
  return s;
}
