function makeCategoryCard(x, y, iconId, title, amount, items){
  const card = figma.createFrame(); card.name="Category_"+title;
  card.x=x; card.y=y; card.resize(335, 8); card.fills=[];
  const catHead = figma.getNodeById("10:38").createInstance();
  catHead.x=0; catHead.y=0; card.appendChild(catHead);
  const iconBg = catHead.findOne(n=>n.name==="iconBg");
  if(iconBg) iconBg.fills=solid({r:0.95,g:0.92,b:1.0});
  await setText(catHead.findOne(n=>n.name==="catTitle"), title);
  await setText(catHead.findOne(n=>n.name==="catAmount"), amount);
  const icon = figma.getNodeById(iconId).createInstance();
  icon.x=25; icon.y=18; icon.resize(18,18); catHead.appendChild(icon);
  for(const v of icon.findAll(n=>n.type==="VECTOR")) { v.fills=solid(BRAND); }
  let yy=56;
  for(const it of items){
    const row = figma.getNodeById("10:31").createInstance();
    row.x=0; row.y=yy; card.appendChild(row);
    await setText(row.findOne(n=>n.name==="rowLabel"), it.label);
    await setText(row.findOne(n=>n.name==="rowAmount"), it.amount);
    await setText(row.findOne(n=>n.name==="rowLeft"), "Left "+it.left);
    await setText(row.findOne(n=>n.name==="rowPct"), it.pct+"%");
    const fill = row.findOne(n=>n.name==="fill" && n.type==="RECTANGLE");
    if(fill){ fill.resize(Math.round(241*it.pct/100), 6); fill.fills=solid(it.color); }
    const trk = row.findOne(n=>n.name==="track" && n.type==="RECTANGLE");
    if(trk) trk.fills=solid({r:0.9,g:0.91,b:0.95});
    yy += 58;
  }
  card.resize(335, yy);
  return card;
}

