function dump(n,d){
  let s="";
  for(const c of n.children){
    s += "  ".repeat(d) + c.type+" "+JSON.stringify(c.name);
    if(c.type==="INSTANCE" && "overrides" in c) s += " ov="+JSON.stringify(c.componentProperties);
    if(c.strokes && c.strokes.length) s += " stroke="+JSON.stringify(c.strokes[0].type)+":"+JSON.stringify(c.strokes[0].color);
    if(c.fills && c.fills[0] && c.fills[0].type==="SOLID") s += " fill="+JSON.stringify(c.fills[0].color);
    s+="\n";
    if(c.children&&c.children.length) s+=dump(c,d+1);
  }
  return s;
}
