// helper: create instance
function inst(compId,x,y,w,h){
  const c = figma.getNodeById(compId);
  const i = c.createInstance();
  i.x=x; i.y=y;
  if(w) i.resize(w,h);
  return i;
}
// helper: find descendant by name
function find(n,name){
  if(n.name===name) return n;
  if("children" in n){for(const c of n.children){const r=find(c,name); if(r)return r;}}
  return null;
}
// helper: recolor icon strokes/fills
function recolor(n,color,ignoreName){
  for(const c of n.children){
    if(c.type==="VECTOR"){
      try{ if(c.strokes&&c.strokes.length) c.strokes=[{type:"SOLID",color}]; }catch(e){}
      try{ if(c.fills&&c.fills.length&&c.fills[0].type==="SOLID") c.fills=[{type:"SOLID",color}]; }catch(e){}
    } else if (c.type==="INSTANCE"){
      recolor(c,color);
    }
  }
}
// set text helper
function setTxt(n,v){ n.characters=v; }

